"use strict";

function uxSafe(value){
  return String(value??"").replace(/[&<>"']/g,function(ch){return({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[ch])});
}

if(typeof quizPartLecture==="function"){
  const coreQuizPartLecture=quizPartLecture;
  quizPartLecture=function(partId){
    const p=quizParts&&quizParts[partId];
    if(p&&p.set==="midterm")return "Midterm Mock";
    return coreQuizPartLecture(partId);
  };
}

