function rebuildS2DeepDive(){
  const card=document.getElementById("summary-s2");
  if(!card||typeof renderSummaryDeepDives!=="function")return;
  const old=card.querySelector(".summary-deep-dive");
  if(old)old.remove();
  renderSummaryDeepDives();
}

function noteTypeLabel(x){
  if(x.kind==="progress")return "TOPIC NOTE";
  if(x.kind==="section")return "QUIZ SECTION NOTE";
  return "QUIZ QUESTION NOTE";
}
function buildAiNotesPack(){
  if(typeof getAllSavedNotes!=="function"||!state)return{count:0,text:""};
  const items=getAllSavedNotes();
  const header=[
    "D STUDY APP — AI NOTES / MISTAKE PACK",
    "Profile: "+(activeUser&&activeUser.username?activeUser.username:"Local profile"),
    "",
    "Purpose:",
    "This pack contains ONLY my own saved notes, mistakes, uncertainties, and quiz-note context from D Study App. It is not the full lecture summary.",
    "",
    "Instructions for ChatGPT:",
    "- Summarize the misunderstandings and weak points shown in my notes.",
    "- Group repeated confusion into a smaller set of concepts I should revisit.",
    "- Explain the minimum course context needed to resolve each confusion.",
    "- Preserve the question/section/topic context written below.",
    "- Point out patterns in my mistakes or uncertainty.",
    "- Give me a short prioritized revision list at the end.",
    "- Do not pretend an image attachment was read; tell me which attached image names I should upload if needed.",
    "",
    "================ SAVED NOTES ================"
  ];
  if(!items.length){
    return{count:0,text:header.concat(["","No saved notes yet."]).join("\n")};
  }
  const lectureOrder=[...new Set(items.map(function(x){return x.lecture||"Other"}))];
  const out=[...header];
  lectureOrder.forEach(function(lecture){
    out.push("","## "+lecture);
    items.filter(function(x){return (x.lecture||"Other")===lecture}).forEach(function(x){
      out.push("","["+noteTypeLabel(x)+"] "+String(x.title||"Untitled"));
      out.push("Context: "+String(x.meta||""));
      const value=String(x.value||"").trim();
      out.push("My note: "+(value||"[No text note — image attachment only]"));
      let media=[];
      try{media=getNoteMedia(x.kind,x.key)||[]}catch(e){}
      if(media.length){
        out.push("Image attachments: "+media.map(function(m,i){return String(m.name||("image-"+(i+1)))}).join(", "));
      }
    });
  });
  return{count:items.length,text:out.join("\n")};
}
function updateAiNotesPack(){
  const card=document.getElementById("notesAiPackCard");
  const box=document.getElementById("notesAiPack");
  const status=document.getElementById("notesAiPackStatus");
  if(!card||!box)return;
  const pack=buildAiNotesPack();
  box.value=pack.text;
  if(status)status.textContent=pack.count?pack.count+" saved note"+(pack.count===1?"":"s")+" included • notes only, not the full summary":"No saved notes yet";
  const copy=document.getElementById("notesAiCopy");
  const download=document.getElementById("notesAiDownload");
  if(copy)copy.disabled=!pack.count;
  if(download)download.disabled=!pack.count;
}
async function copyAiNotesPack(){
  const box=document.getElementById("notesAiPack");
  const status=document.getElementById("notesAiPackStatus");
  if(!box||!box.value)return;
  try{await navigator.clipboard.writeText(box.value)}
  catch(e){box.focus();box.select();document.execCommand("copy")}
  if(status){const previous=status.textContent;status.textContent="Copied AI Notes Pack ✓";setTimeout(function(){updateAiNotesPack()},1500)}
}
function downloadAiNotesPack(){
  const pack=buildAiNotesPack();if(!pack.count)return;
  const blob=new Blob([pack.text],{type:"text/plain;charset=utf-8"});
  const a=document.createElement("a");
  const user=(activeUser&&activeUser.username?activeUser.username:"profile").replace(/[^a-z0-9_-]+/gi,"-");
  a.href=URL.createObjectURL(blob);
  a.download="d-study-"+user+"-ai-notes-pack.txt";
  document.body.appendChild(a);a.click();a.remove();
  setTimeout(function(){URL.revokeObjectURL(a.href)},1000);
}

function bindAiNotesPack(){
  const copy=document.getElementById("notesAiCopy"),download=document.getElementById("notesAiDownload"),refresh=document.getElementById("notesAiRefresh");
  if(copy&&!copy.dataset.bound){copy.dataset.bound="1";copy.onclick=copyAiNotesPack}
  if(download&&!download.dataset.bound){download.dataset.bound="1";download.onclick=downloadAiNotesPack}
  if(refresh&&!refresh.dataset.bound){refresh.dataset.bound="1";refresh.onclick=updateAiNotesPack}
  const panel=document.getElementById("notes");
  if(panel&&!panel.dataset.aiPackWatch){
    panel.dataset.aiPackWatch="1";
    ["input","change","click"].forEach(function(ev){
      panel.addEventListener(ev,function(e){
        if(e.target&&e.target.closest&&e.target.closest("#notesAiPackCard"))return;
        setTimeout(updateAiNotesPack,0);
      });
    });
  }
  updateAiNotesPack();
}

function summaryDocLabel(doc){
  const first=[...doc.children].find(function(el){return el.classList&&el.classList.contains("card")});
  const label=first&&first.querySelector(".lecture-title");
  return label?label.textContent.trim():doc.id;
}
function summarySearchIndex(){
  const rows=[];
  document.querySelectorAll(".summary-doc").forEach(function(doc){
    [...doc.querySelectorAll(".slide-card")].forEach(function(card,i){
      if(!card.id)card.id="summary-search-"+doc.id+"-"+(i+1);
      const title=(card.querySelector("h2")&&card.querySelector("h2").textContent.trim())||("Summary section "+(i+1));
      const slide=(card.querySelector(".slide-no")&&card.querySelector(".slide-no").textContent.trim())||"";
      rows.push({docId:doc.id,cardId:card.id,title:title,slide:slide,lecture:summaryDocLabel(doc),text:card.textContent.replace(/\s+/g," ").trim()});
    });
  });
  return rows;
}
function summarySnippet(text,terms){
  const lower=text.toLowerCase();
  let at=-1;
  terms.some(function(t){at=lower.indexOf(t);return at>=0});
  if(at<0)at=0;
  const start=Math.max(0,at-70),end=Math.min(text.length,at+190);
  return (start>0?"…":"")+text.slice(start,end)+(end<text.length?"…":"");
}
function runSummarySearch(){
  const input=document.getElementById("summarySearch"),results=document.getElementById("summarySearchResults"),meta=document.getElementById("summarySearchMeta");
  if(!input||!results)return;
  const q=input.value.trim().toLowerCase();
  if(!q){
    results.innerHTML='<div class="summary-search-empty">Search any word or idea to scan every current lecture summary at once.</div>';
    if(meta)meta.textContent="Searches all summary blocks";
    return;
  }
  const terms=q.split(/\s+/).filter(Boolean);
  const matches=summarySearchIndex().filter(function(x){
    const hay=x.text.toLowerCase();
    return terms.every(function(t){return hay.includes(t)});
  }).slice(0,30);
  if(meta)meta.textContent=matches.length+" result"+(matches.length===1?"":"s")+" across all lectures";
  if(!matches.length){
    results.innerHTML='<div class="summary-search-empty">No summary context matched “'+uxSafe(input.value.trim())+'”. Try a broader term.</div>';
    return;
  }
  results.innerHTML=matches.map(function(x){
    return '<button type="button" class="summary-search-result" data-summary-search-doc="'+uxSafe(x.docId)+'" data-summary-search-card="'+uxSafe(x.cardId)+'"><span class="summary-search-source">'+uxSafe(x.lecture)+(x.slide?" • "+uxSafe(x.slide):"")+'</span><b>'+uxSafe(x.title)+'</b><span>'+uxSafe(summarySnippet(x.text,terms))+'</span></button>';
  }).join("");
  results.querySelectorAll("[data-summary-search-card]").forEach(function(btn){
    btn.onclick=function(){
      const docId=btn.dataset.summarySearchDoc,cardId=btn.dataset.summarySearchCard;
      openSummaryDoc(docId);
      setTimeout(function(){
        const card=document.getElementById(cardId);
        if(card){
          card.classList.add("summary-search-hit");
          card.scrollIntoView({behavior:"smooth",block:"start"});
          setTimeout(function(){card.classList.remove("summary-search-hit")},2200);
        }
      },80);
    };
  });
}
function bindSummarySearch(){
  const input=document.getElementById("summarySearch"),clear=document.getElementById("summarySearchClear");
  if(input&&!input.dataset.bound){
    input.dataset.bound="1";input.oninput=runSummarySearch;
    input.onkeydown=function(e){if(e.key==="Escape"){input.value="";runSummarySearch();input.blur()}};
  }
  if(clear&&!clear.dataset.bound){clear.dataset.bound="1";clear.onclick=function(){input.value="";runSummarySearch();input.focus()}}
  runSummarySearch();
}

